import{_ as t,o as a,c as r,a5 as s}from"./chunks/framework.DrDMl0tG.js";const p=JSON.parse('{"title":"Server Example: Underwater ROV","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/underwater_rov.md","filePath":"sections/examples/server/underwater_rov.md"}'),i={name:"sections/examples/server/underwater_rov.md"};function o(n,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-underwater-rov" tabindex="-1">Server Example: Underwater ROV <a class="header-anchor" href="#server-example-underwater-rov" aria-label="Permalink to &quot;Server Example: Underwater ROV&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A remotely operated vehicle holds its station 3 m under the sea (<a href="./../../Fluids.html">Fluids</a>) with six thrusters. The current runs at 0.5 m/s and turns by a quarter every eight seconds.</p><ul><li>The sea holds the vehicle up a little more than its weight, so the vertical thrusters push it down.</li><li>The sea drags the vehicle with the current and moves the water around it with it (its added mass).</li><li>Its foam block and skids put its center of mass below its center of buoyancy, so it stays level by itself.</li><li>A proportional-integral-derivative controller keeps its position and heading.</li></ul><p>Each time the current turns, it pushes the vehicle up to 9 cm off its station, and the vehicle comes back to within 7 mm before the current turns again. The cyan arrow shows the current. The ROV hovers above a rocky survey site with textured sand, seagrass, sea fans, shells and an acoustic lander. Its detailed shell includes six thruster ducts, a camera port, work lamps and protective rails; an orange tether follows it toward the surface.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>underwater_rov</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/underwater_rov</span></span></code></pre></div><p>Connect <code>rayrai_tcp_viewer</code> to port 8080. On Windows, run <code>build-examples/bin/underwater_rov.exe</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The vehicle is a compound of a hull, a foam block and two skids. It displaces 90.8 kg of sea water and weighs 88 kg.</li><li>The thrusters push at fixed points of the vehicle (<code>setExternalForce()</code> with a position). Four vectored ones in the horizontal plane give the force along x and y and the torque about z, and two vertical ones the force along z. A pseudo-inverse of their effects allocates the thrust, which is limited to 60 N each.</li><li>The current is the velocity of the <code>FluidVolume</code>, changed with <code>World::setFluidVolume()</code>.</li><li>The physics scene lives in <code>include/fluid_rov.hpp</code>. The environment and lighting come from <code>rsc/underwater_rov/underwater_rov.rscene</code>, which the server shares with the TCP viewer. The decorative meshes add no collision or buoyancy geometry. The complete asset dependency set is about 12 MB, below the 200 MB budget; source and license details are in the asset directory.</li><li><code>underwater_rov_scene_benchmark</code> in the source repository compares scene loading and physics step time with and without the environment.</li></ul>',12)])])}const v=t(i,[["render",o]]);export{p as __pageData,v as default};
